import React from "react";

export default function Dashboard() {

const user = JSON.parse(
localStorage.getItem("user")
);

return (

<div
style={{
height:"100vh",
display:"flex",
flexDirection:"column",
justifyContent:"center",
alignItems:"center",
background:"#0f172a",
color:"white"
}}
>

<h1>

Welcome to RBAC Dashboard 🎉

</h1>

<h2>

Name : {user?.name}

</h2>

<h3>

Email : {user?.email}

</h3>

<h3>

Role : {user?.role}

</h3>

</div>

);

}
